INSERT INTO `ai_playerbot_texts` (`id`, `name`, `text`, `say_type`, `reply_type`, `text_loc1`, `text_loc2`, `text_loc3`, `text_loc4`, `text_loc5`, `text_loc6`, `text_loc7`, `text_loc8`) VALUES
	(2400, 'broadcast_guild_raid_anyone', 'Anyone up for a raid in %zone_name?', 0, 0, '%zone_name 공격대 잡으실 분?', 'Quelqu''un pour un raid à %zone_name ?', 'Wer Lust auf einen Raid in %zone_name?', '有人在 %zone_name 开团吗？', '有人在 %zone_name 開團嗎？', '¿Alguien para raid en %zone_name?', '¿Alguien para raid en %zone_name?', 'Кто на рейд в %zone_name?'),
	(2401, 'broadcast_guild_raid_invite_name', 'Hey %name, I''m raiding in %zone_name — want to come?', 0, 0, '%name, %zone_name에서 공대 중인데 같이 갈래?', 'Salut %name, je suis en raid à %zone_name — tu viens ?', 'Hey %name, ich bin in %zone_name am Raiden — kommst du mit?', '嘿 %name，我在 %zone_name 开团，一起来吗？', '嘿 %name，我在 %zone_name 開團，一起來嗎？', 'Oye %name, estoy raideando en %zone_name — ¿vienes?', 'Oye %name, estoy raideando en %zone_name — ¿vienes?', 'Эй %name, я в рейде в %zone_name — пойдёшь?'),
	(2402, 'broadcast_guild_group_anyone', 'Anyone want to group up in %zone_name?', 0, 0, '%zone_name에서 파티 하실 분?', 'Quelqu''un pour un groupe à %zone_name ?', 'Wer will in %zone_name eine Gruppe machen?', '有人在 %zone_name 组队吗？', '有人在 %zone_name 組隊嗎？', '¿Alguien para grupo en %zone_name?', '¿Alguien para grupo en %zone_name?', 'Кто в группу в %zone_name?'),
	(2403, 'broadcast_guild_group_invite_name', 'Hey %name, I''m heading to %zone_name — join my group?', 0, 0, '%name, %zone_name로 가는데 파티 같이 할래?', 'Salut %name, je file à %zone_name — tu rejoins mon groupe ?', 'Hey %name, ich gehe nach %zone_name — willst du in meine Gruppe?', '嘿 %name，我要去 %zone_name，一起组队吗？', '嘿 %name，我要去 %zone_name，一起組隊嗎？', 'Oye %name, voy a %zone_name — ¿te unes a mi grupo?', 'Oye %name, voy a %zone_name — ¿te unes a mi grupo?', 'Эй %name, я иду в %zone_name — в группу?'),
	(2404, 'broadcast_posted_trade', 'Poking trade chat… %rand1 %rand2 %rand3 — anyone selling?', 0, 0, '거래 채널에 한마디… %rand1 %rand2 %rand3 — 파시는 분?', 'Un petit tour sur le commerce… %rand1 %rand2 %rand3 — des vendeurs ?', 'Kurz im Handelskanal… %rand1 %rand2 %rand3 — wer verkauft?', '交易频道冒个泡… %rand1 %rand2 %rand3，有人出货吗？', '交易頻道冒個泡… %rand1 %rand2 %rand3，有人出貨嗎？', 'Pasando por comercio… %rand1 %rand2 %rand3 — ¿alguien vende?', 'Pasando por comercio… %rand1 %rand2 %rand3 — ¿alguien vende?', 'Заглянул в торговлю… %rand1 %rand2 %rand3 — кто продаёт?'),
	(2405, 'broadcast_posted_guild_recruitment', 'Recruiting in guild chat… %rand1 %rand2 %rand3 — looking for friendly folks!', 0, 0, '길드 모집 중… %rand1 %rand2 %rand3 — 같이 놀 분 구해요!', 'Recrutement en cours… %rand1 %rand2 %rand3 — on cherche des gens sympas !', 'Rekrutiere gerade… %rand1 %rand2 %rand3 — suche lockere Mitspieler!', '公会招募中… %rand1 %rand2 %rand3，找一起玩的！', '公會招募中… %rand1 %rand2 %rand3，找一起玩的！', 'Reclutando… %rand1 %rand2 %rand3 — buscamos gente maja.', 'Reclutando… %rand1 %rand2 %rand3 — buscamos gente maja.', 'Набираем в гильдию… %rand1 %rand2 %rand3 — ищем своих!'),
	(2406, 'broadcast_posted_guild', 'Guild chat check-in… %rand1 %rand2 %rand3 — how''s everyone doing?', 0, 0, '길드 채널 인사… %rand1 %rand2 %rand3 — 다들 잘 지내?', 'Petit coucou guilde… %rand1 %rand2 %rand3 — ça va tout le monde ?', 'Kurz im Gildenchat… %rand1 %rand2 %rand3 — wie läuft''s?', '公会频道报到… %rand1 %rand2 %rand3，大家都好吗？', '公會頻道報到… %rand1 %rand2 %rand3，大家都好嗎？', 'Saludos en hermandad… %rand1 %rand2 %rand3 — ¿qué tal?', 'Saludos en hermandad… %rand1 %rand2 %rand3 — ¿qué tal?', 'Заглянул в гильд-чат… %rand1 %rand2 %rand3 — как дела?'),
	(2407, 'broadcast_posted_world', 'World chat moment… %rand1 %rand2 %rand3 — anyone awake?', 0, 0, '월드 채널 한마디… %rand1 %rand2 %rand3 — 깨어 있는 분?', 'Un passage sur le monde… %rand1 %rand2 %rand3 — quelqu''un de réveillé ?', 'Kurz im Weltchat… %rand1 %rand2 %rand3 — wer ist wach?', '世界频道冒泡… %rand1 %rand2 %rand3，还有活人吗？', '世界頻道冒泡… %rand1 %rand2 %rand3，還有活人嗎？', 'Un momento en mundo… %rand1 %rand2 %rand3 — ¿alguien despierto?', 'Un momento en mundo… %rand1 %rand2 %rand3 — ¿alguien despierto?', 'Мир-чат… %rand1 %rand2 %rand3 — кто не спит?'),
	(2408, 'broadcast_posted_general', 'General chat hello… %rand1 %rand2 %rand3 — quiet today?', 0, 0, '일반 채널 인사… %rand1 %rand2 %rand3 — 오늘 조용하네?', 'Coucou sur le général… %rand1 %rand2 %rand3 — c''est calme aujourd''hui ?', 'Kurz im Allgemeinen… %rand1 %rand2 %rand3 — heute ruhig?', '综合频道打个招呼… %rand1 %rand2 %rand3，今天好安静？', '綜合頻道打個招呼… %rand1 %rand2 %rand3，今天好安靜？', 'Hola en general… %rand1 %rand2 %rand3 — ¿tan callado hoy?', 'Hola en general… %rand1 %rand2 %rand3 — ¿tan callado hoy?', 'Общий канал… %rand1 %rand2 %rand3 — сегодня тихо?'),
	(2409, 'broadcast_posted_lfg', 'LFG ping… %rand1 %rand2 %rand3 — need a group?', 0, 0, '파티 찾기… %rand1 %rand2 %rand3 — 같이 갈 사람?', 'Recherche de groupe… %rand1 %rand2 %rand3 — besoin d''une équipe ?', 'LFG… %rand1 %rand2 %rand3 — wer braucht eine Gruppe?', '寻求组队… %rand1 %rand2 %rand3，有人一起吗？', '尋求組隊… %rand1 %rand2 %rand3，有人一起嗎？', 'Buscando grupo… %rand1 %rand2 %rand3 — ¿alguien?', 'Buscando grupo… %rand1 %rand2 %rand3 — ¿alguien?', 'LFG… %rand1 %rand2 %rand3 — кто в группу?'),
	(2410, 'broadcast_posted_local_defense', 'Local defense… %rand1 %rand2 %rand3 — all clear out there?', 0, 0, '지역 방어… %rand1 %rand2 %rand3 — 주변 괜찮아?', 'Défense locale… %rand1 %rand2 %rand3 — tout va bien ?', 'Lokale Verteidigung… %rand1 %rand2 %rand3 — alles ruhig?', '本地防务… %rand1 %rand2 %rand3，附近安全吗？', '本地防務… %rand1 %rand2 %rand3，附近安全嗎？', 'Defensa local… %rand1 %rand2 %rand3 — ¿todo bien?', 'Defensa local… %rand1 %rand2 %rand3 — ¿todo bien?', 'Местная оборона… %rand1 %rand2 %rand3 — тихо?'),
	(2411, 'broadcast_posted_world_defense', 'World defense… %rand1 %rand2 %rand3 — keep your eyes open.', 0, 0, '세계 방어… %rand1 %rand2 %rand3 — 조심해.', 'Défense mondiale… %rand1 %rand2 %rand3 — restez vigilants.', 'Weltverteidigung… %rand1 %rand2 %rand3 — Augen auf.', '世界防务… %rand1 %rand2 %rand3，大家留神。', '世界防務… %rand1 %rand2 %rand3，大家留神。', 'Defensa mundial… %rand1 %rand2 %rand3 — ojo avizor.', 'Defensa mundial… %rand1 %rand2 %rand3 — ojo avizor.', 'Мировая оборона… %rand1 %rand2 %rand3 — будьте начеку.'),
	(2412, 'guild_invite_hey_want_join', 'Hey %name, want to join my guild?', 0, 0, '안녕 %name, 우리 길드 들어올래?', 'Salut %name, tu veux rejoindre ma guilde ?', 'Hey %name, Lust meiner Gilde beizutreten?', '嘿 %name，要不要加入我们公会？', '嘿 %name，要不要加入我們公會？', 'Oye %name, ¿te apuntas a mi hermandad?', 'Oye %name, ¿te apuntas a mi hermandad?', 'Эй %name, хочешь в нашу гильдию?'),
	(2413, 'guild_invite_hey_man', 'Hey %name, wanna roll with our guild?', 0, 0, '야 %name, 우리 길드랑 같이 할래?', 'Hé %name, envie de jouer avec notre guilde ?', 'Hey %name, Lust mit unserer Gilde zu spielen?', '嘿 %name，要不要来我们公会一起混？', '嘿 %name，要不要來我們公會一起混？', 'Oye %name, ¿te unes a nuestra hermandad?', 'Oye %name, ¿te unes a nuestra hermandad?', 'Эй %name, хочешь с нашей гильдией?'),
	(2414, 'guild_invite_good_contribution', 'You''d be a great fit for %guildname, %name — interested?', 0, 0, '%name, %guildname에 꼭 어울릴 것 같은데 — 들어올래?', 'Tu collerais bien à %guildname, %name — ça te dit ?', 'Du würdest super in %guildname passen, %name — Interesse?', '%name，你很适合 %guildname，有兴趣吗？', '%name，你很適合 %guildname，有興趣嗎？', 'Encajarías genial en %guildname, %name — ¿te interesa?', 'Encajarías genial en %guildname, %name — ¿te interesa?', 'Ты отлично впишешься в %guildname, %name — как насчёт?'),
	(2415, 'guild_invite_quality_members', '%guildname already has %members solid players — room for you too, %name?', 0, 0, '%guildname에 벌써 %members명이나 있는데, %name도 같이 할래?', '%guildname compte déjà %members joueurs — il reste une place pour toi, %name ?', '%guildname hat schon %members Leute — Platz für dich auch, %name?', '%guildname 已有 %members 位老手，%name 要不要也来？', '%guildname 已有 %members 位老手，%name 要不要也來？', '%guildname ya tiene %members jugadores — ¿te apuntas, %name?', '%guildname ya tiene %members jugadores — ¿te apuntas, %name?', 'В %guildname уже %members человек — место для тебя тоже, %name?'),
	(2416, 'guild_invite_number_one', 'Hey %name, join %guildname? We''re %members strong and aiming for #1 on the server.', 0, 0, '%name, %guildname 들어올래? %members명이고 서버 1위가 목표야.', 'Salut %name, tu rejoins %guildname ? On est %members et on vise le top serveur.', 'Hey %name, Lust auf %guildname? Wir sind %members und wollen Server-Nr. 1.', '嘿 %name，来 %guildname 吗？我们 %members 人，目标是全服第一。', '嘿 %name，來 %guildname 嗎？我們 %members 人，目標是全服第一。', 'Oye %name, ¿te unes a %guildname? Somos %members y vamos a por el nº1.', 'Oye %name, ¿te unes a %guildname? Somos %members y vamos a por el nº1.', 'Эй %name, в %guildname? Нас %members, цель — топ сервера.'),
	(2417, 'guild_invite_no_smalltalk', 'I''m bad at small talk — just join %guildname, %name?', 0, 0, '수다는 짧게 — %guildname 들어올래, %name?', 'Je suis nul en blabla — rejoins %guildname, %name ?', 'Kein Smalltalk — tritt %guildname bei, %name?', '我不会闲聊——直接加 %guildname 吧，%name？', '我不會閒聊——直接加 %guildname 吧，%name？', 'Malísimo charlando — únete a %guildname, %name.', 'Malísimo charlando — únete a %guildname, %name.', 'Без лишних слов — в %guildname, %name?'),
	(2418, 'guild_invite_welcome_zone', 'Welcome to %zone_name, %name — want to join our guild while you''re here?', 0, 0, '%zone_name에 온 %name, 잠깐 우리 길드 들어올래?', 'Bienvenue à %zone_name, %name — envie de rejoindre notre guilde ?', 'Willkommen in %zone_name, %name — Lust auf unsere Gilde?', '欢迎来到 %zone_name，%name——顺便加入我们公会？', '歡迎來到 %zone_name，%name——順便加入我們公會？', 'Bienvenido a %zone_name, %name — ¿te unes a nuestra hermandad?', 'Bienvenido a %zone_name, %name — ¿te unes a nuestra hermandad?', 'Добро пожаловать в %zone_name, %name — может, в нашу гильдию?'),
	(2419, 'guild_invite_should_join', '%name, you really should join our guild!', 0, 0, '%name, 우리 길드 들어와야 해!', '%name, tu devrais vraiment nous rejoindre !', '%name, du solltest wirklich zu uns kommen!', '%name，你真的该加入我们公会！', '%name，你真的該加入我們公會！', '%name, ¡deberías unirte a nuestra hermandad!', '%name, ¡deberías unirte a nuestra hermandad!', '%name, тебе правда стоит к нам!'),
	(2420, 'guild_invite_got_guild', '%name, I''ve got this guild going…', 0, 0, '%name, 나 길드 운영 중인데…', '%name, j''ai monté cette guilde…', '%name, ich hab da so eine Gilde…', '%name，我这有个公会……', '%name，我這有個公會……', '%name, tengo esta hermandad…', '%name, tengo esta hermandad…', '%name, у меня тут гильдия…'),
	(2421, 'guild_invite_going_to_join', 'Wait, you''re actually joining, %name?', 0, 0, '잠깐, %name 진짜 들어올 거야?', 'Attends, tu viens vraiment, %name ?', 'Moment, du trittst wirklich bei, %name?', '等等，%name 你是真要加吗？', '等等，%name 你是真要加嗎？', 'Espera, ¿de verdad te unes, %name?', 'Espera, ¿de verdad te unes, %name?', 'Погоди, ты правда идёшь к нам, %name?'),
	(2422, 'guild_invite_raid_molten', 'Haha, legend! Next stop: Molten Core…', 0, 0, '하하, 대박! 다음은 화심…', 'Haha, t''es un crack ! Prochaine étape : Cœur du Magma…', 'Haha, du bist der Wahnsinn! Nächster Stopp: Molten Core…', '哈哈，牛逼！下一站：熔火之心……', '哈哈，牛逼！下一站：熔火之心……', 'Jaja, ¡crack! Siguiente parada: Núcleo de Magma…', 'Jaja, ¡crack! Siguiente parada: Núcleo de Magma…', 'Ха-ха, красава! Дальше — Огненное Ядро…'),
	(2423, 'guild_invite_hey_gild', 'Hey hey! Anyone want in on our guild????', 0, 0, '야야! 우리 길드 들어올 사람????', 'Hé hé ! Qui veut rejoindre notre guilde ????', 'Hey hey! Wer will in unsere Gilde ????', '嘿嘿！有人要进我们公会吗？？？？', '嘿嘿！有人要進我們公會嗎？？？？', '¡Oye oye! ¿Quién se apunta a nuestra hermandad????', '¡Oye oye! ¿Quién se apunta a nuestra hermandad????', 'Эй-эй! Кто в нашу гильдию????'),
	(2424, 'guild_invite_friendly_high_levels', 'We''ve got plenty of high levels and we''re actually nice…', 0, 0, '고레벨도 많고 분위기도 좋아…', 'Plein de hauts niveaux et on est vraiment sympas…', 'Viele Highlevels und wir sind echt nett…', '高等级不少，而且人挺好……', '高等級不少，而且人挺好……', 'Montones de high levels y somos majos de verdad…', 'Montones de high levels y somos majos de verdad…', 'Полно высоких уровней и мы нормальные…'),
	(2425, 'guild_invite_homework', '…we''ll walk your dog and help with homework…', 0, 0, '…개도 봐주고 숙제도 도와준다…', '…on garde ton chien et on t''aide aux devoirs…', '…wir gehen mit deinem Hund Gassi und helfen bei den Hausaufgaben…', '……还能帮你遛狗、辅导作业……', '……還能幫你遛狗、輔導作業……', '…paseamos tu perro y te ayudamos con los deberes…', '…paseamos tu perro y te ayudamos con los deberes…', '…выгуляем собаку и с уроками поможем…'),
	(2426, 'guild_invite_mc_raids', '…weekly raids, working on MC right now…', 0, 0, '…주 1회 공대, 지금 화심 공략 중…', '…un raid par semaine, on farm MC en ce moment…', '…wöchentlich raiden, gerade MC am Laufen…', '……每周团本，正在推熔火……', '……每週團本，正在推熔火……', '…raid semanal, ahora con MC…', '…raid semanal, ahora con MC…', '…рейд раз в неделю, сейчас MC…'),
	(2427, 'guild_invite_more_members', '…and no, it''s not just me in here…', 0, 0, '…참고로 나 혼자만 있는 게 아니야…', '…et non, je ne suis pas tout seul…', '…und nein, ich bin nicht allein…', '……而且不止我一个人……', '……而且不止我一個人……', '…y no, no estoy solo…', '…y no, no estoy solo…', '…и нет, я тут не один…'),
	(2428, 'guild_invite_lonely', '…please stop, I''m lonely — we''ll carry you all day…', 0, 0, '…제발, 외로워 — 하루 종일 같이 다니자…', '…arrête, je suis seul — on te carry toute la journée…', '…bitte, ich bin einsam — wir carryn dich den ganzen Tag…', '……别说了我好寂寞，可以带你刷一整天……', '……別說了我好寂寞，可以帶你刷一整天……', '…para ya, estoy solo — te llevamos todo el día…', '…para ya, estoy solo — te llevamos todo el día…', '…хватит, мне одиноко — будем таскать весь день…'),
	(2429, 'guild_invite_crying', '…it''s so beautiful I could cry…', 0, 0, '…너무 감동적이라 울 것 같아…', '…c''est tellement beau que j''en pleure…', '…so schön, ich könnte weinen…', '……太感人了，我要哭了……', '……太感人了，我要哭了……', '…es tan bonito que lloro…', '…es tan bonito que lloro…', '…так трогательно, что хочется плакать…'),
	(2430, 'guild_invite_so_join', 'So — are you in or not? In or not?', 0, 0, '자, 들어온다? 말다?', 'Alors — tu viens ou pas ? Oui ou non ?', 'Also — bist du dabei oder nicht?', '所以——加还是不加？加不加？', '所以——加還是不加？加不加？', 'Entonces — ¿sí o no? ¿Sí o no?', 'Entonces — ¿sí o no? ¿Sí o no?', 'Ну что — да или нет? Да или нет?');

